<div class="modal-backdrop" id="websiteModal" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><h2 id="modalTitle">Tambah website</h2><p id="modalDesc">Masukkan alamat website yang ingin dipantau.</p></div><button class="close" onclick="closeModal()">✕</button></div><form id="websiteForm" method="POST" action="{{ route('websites.store') }}">@csrf<div id="methodField"></div><div class="field"><label for="name">Nama website</label><input id="name" name="name" placeholder="Contoh: Website utama" maxlength="80" required></div><div class="field"><label for="url">Alamat URL</label><input id="url" name="url" type="url" placeholder="https://contoh.com" required><div class="hint">Gunakan alamat lengkap yang diawali http:// atau https://</div></div><div class="field"><label for="check_interval">Interval pemeriksaan</label><select id="check_interval" name="check_interval"><option value="1">Setiap 1 menit</option><option value="5" selected>Setiap 5 menit</option><option value="10">Setiap 10 menit</option><option value="15">Setiap 15 menit</option><option value="30">Setiap 30 menit</option><option value="60">Setiap 60 menit</option></select></div><div class="form-footer"><button type="button" class="btn btn-quiet" onclick="closeModal()">Batal</button><button class="btn btn-primary" id="saveButton">Simpan website</button></div></form></div></div>
<script>
const modal=document.getElementById('websiteModal'),form=document.getElementById('websiteForm'),methodField=document.getElementById('methodField');
function openCreate(){form.action='{{ route('websites.store') }}';methodField.innerHTML='';document.getElementById('modalTitle').textContent='Tambah website';document.getElementById('modalDesc').textContent='Masukkan alamat website yang ingin dipantau.';document.getElementById('saveButton').textContent='Simpan website';form.reset();modal.classList.add('open');setTimeout(()=>document.getElementById('name').focus(),80)}
function openEdit(id,name,url,interval){form.action=`{{ url('/websites') }}/${id}`;methodField.innerHTML='<input type="hidden" name="_method" value="PUT">';document.getElementById('modalTitle').textContent='Edit website';document.getElementById('modalDesc').textContent='Ubah informasi dan interval pemeriksaan.';document.getElementById('saveButton').textContent='Simpan perubahan';document.getElementById('name').value=name;document.getElementById('url').value=url;document.getElementById('check_interval').value=interval;modal.classList.add('open')}
function closeModal(){modal.classList.remove('open')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
const search=document.getElementById('search'),statusFilter=document.getElementById('statusFilter');
function filterRows(){const q=(search?.value||'').toLowerCase(),s=statusFilter?.value||'all';document.querySelectorAll('.website-row').forEach(row=>{const show=row.dataset.name.includes(q)&&(s==='all'||row.dataset.status===s);row.style.display=show?'':'none';const next=row.nextElementSibling;if(next?.classList.contains('history-row'))next.style.display=show?'':'none'})}
search?.addEventListener('input',filterRows);statusFilter?.addEventListener('change',filterRows);
</script>
</body>
</html>
